        visited = [False] * (n + 1)
        component_vals = {}
        component_constraints = {}

        def solve_component(start):
            local_vals = {}
            local_constraints = {}
            stack = [start]
            local_constraints[start] = {'value': 0.0, 'fixed': False}

            while stack:
                u = stack.pop()
                if u in local_vals:
                    continue

                val_obj = local_constraints.get(u)
                if not val_obj:
                    continue

                is_fixed = val_obj['fixed']
                base_value = val_obj['value']

                for v, color in adj[u]:
                    if v < 1 or v > n:
                        continue

                    if is_fixed:
                        v_val = base_value
                        if color == 1:  # Black: x[u] + x[v] = 1 => x[v] = 1 - x[u]
                            v_base = 1.0 - base_value
                            v_fixed = True
                        else:  # Red: x[u] + x[v] = 2 => x[v] = 2 - x[u]
                            v_base = 2.0 - base_value
                            v_fixed = True
                    else:
                        # Not fixed yet, might need cycle detection
                        if v in local_vals:
                            # Cycle detected - check consistency
                            u_val, u_fixed = val_obj['value'], val_obj['fixed']
                            v_val, v_fixed = local_vals[v]['value'], local_vals[v]['fixed']

                            expected_v = 1.0 - u_val if color == 1 else 2.0 - u_val
                            if not v_fixed and v in local_vals:
                                continue

                            if abs(expected_v - v_val) > 1e-7:
                                return None, None

                    if v not in local_vals or not local_vals[v]['fixed']:
                        local_vals[v] = {'value': v_base, 'fixed': v_fixed}
                        stack.append(v)

        all_vals = [0.0] * (n + 1)

        for start in range(1, n + 1):
            if visited[start]:
                continue

            visited[start] = True
            comp_start = start
            comp_nodes = []

            # BFS to collect component nodes
            q = [start]
            visited_in_comp = {start}
            while q:
                u = q.pop(0)
                comp_nodes.append(u)
                for v, _ in adj[u]:
                    if v not in visited_in_comp and 1 <= v <= n:
                        visited_in_comp.add(v)
                        q.append(v)

            # Now solve for this component
            all_nodes = set(comp_nodes)
            val_assignments = {}
            constraints = []  # (node, coefficient, constant)

            # Set up the system using first node as reference
            ref_node = comp_nodes[0]
            ref_val = 0.0

            # Assign all nodes relative to ref
            order = comp_nodes
            visited_temp = set()
            if ref_node not in visited_temp:
                visited_temp.add(ref_node)

            stack = [ref_node]
            node_order = []

            while stack:
                u = stack.pop()
                if u in visited_temp:
                    continue
                visited_temp.add(u)
                node_order.append(u)

                # Try to find value based on ref
                for v, color in adj[u]:
                    if v == ref_node and u not in val_assignments and ref_node in val_assignments:
                        # Cycle back to ref
                        if color == 1:
                            val_assignments[u] = 1.0 - val_assignments[ref_node]
                        elif color == 2:
                            val_assignments[u] = 2.0 - val_assignments[ref_node]
                        break
                    elif v not in visited_temp and v in val_assignments:
                        if color == 1:
                            val_assignments[u] = 1.0 - val_assignments[v]
                        elif color == 2:
                            val_assignments[u] = 2.0 - val_assignments[v]

                if u not in val_assignments:
                    for v, color in adj[u]:
                        if v in visited_temp:
                            continue
                        if v in val_assignments:
                            stack.append(v)
                            break

            # Simplify: use backtracking to find optimal assignment
            return "OK"

        return "YES\n" + " ".join(f"{all_vals[i]:.6f}" for i in range(1, n + 1))

