        si, ri = map(int, lines[i].split())
        competitors.append((si, ri, i))

    # Transform to (1/s, 1/r) - each competitor is a point
    # A point on the lower convex hull can win for some S, R > 0
    points = []
    for si, ri, idx in competitors:
