    # Compute lower convex hull using monotone chain
    # For lower hull, we keep left turns or collinear points
    hull = []
    for p in unique_points:
        while len(hull) >= 2:
            c1 = hull[-2]
            c2 = hull[-1]
            c3 = p
            # Cross product: (x2-x1)*(y3-y1) - (y2-y1)*(x3-x1)
            cross = (c2[0] - c1[0]) * (c3[1] - c1[1]) - (c2[1] - c1[1]) * (c3[0] - c1[0])
            # For lower hull, keep if cross <= 0 (left turn or collinear)
            if cross > 0:
                hull.pop()
            else:
                break
        hull.append(p)

    # Extract competitor indices and sort them
    result = [p[2] for p in hull]
    result.sort()

    # Format output
