from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "-1\n"

    try:
        a = list(map(int, lines[0].split()))
        b = list(map(int, lines[1].split()))
    except:
        return "-1\n"

    n = len(a)

    # State representation for BFS: sorted tuple of positions
    target_sorted = tuple(sorted(b))

    # Quick impossibility checks
    # If all initial positions are the same, we can't make any moves
    if len(set(a)) == 1:
        sorted_a = tuple(sorted(a))
        if sorted_a == target_sorted:
            return "0\n"
        return "-1\n"

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return abs(x)

    # Compute gcd of pairwise differences for initial positions
    initial_gcds = []
    for i in range(n):
        for j in range(i + 1, n):
            initial_gcds.append(abs(a[i] - a[j]))

    # Compute gcd of pairwise differences for target positions
    target_gcds = []
    for i in range(n):
        for j in range(i + 1, n):
            target_gcds.append(abs(b[i] - b[j]))

    initial_gcd = gcd(initial_gcds[0], initial_gcds[1])
    for g in initial_gcds[2:]:
        initial_gcd = gcd(initial_gcd, g)

    target_gcd = gcd(target_gcds[0], target_gcds[1])
    for g in target_gcds[2:]:
        target_gcd = gcd(target_gcd, g)

    # If gcd of differences doesn't match, impossible
    if initial_gcd != target_gcd:
        return "-1\n"

    # BFS to find solution
    # State: sorted tuple of current positions
    MAX_OPERATIONS = 1000

    start_state = tuple(sorted(a))
    visited = set([start_state])

    # Queue: (state, operations_list)
    queue = deque([(start_state, [])])

    for _ in range(MAX_OPERATIONS + 1):
        if not queue:
            break

        state, ops = queue.popleft()

        if state == target_sorted:
            # Reconstruct operations
            result = []
            result.append(str(len(ops)))
            for op in ops:
                result.append(f"{op[0]} {op[1]}")
            return "\n".join(result) + "\n"

        # Count stones at each position in current state
        pos_count = {}
        for pos in state:
            pos_count[pos] = pos_count.get(pos, 0) + 1

        # Find all possible moves
        # A move is: stone from position x -> position 2y-x
        # Need at least one stone at x and y

        sorted_persons = [token for token in deque(sorted(list(state)))][0]

        # Generate possible next states by trying all legal moves
        for i, from_pos in enumerate(state):
            # Skip if no stone here
            if pos_count[from_pos] == 0:
                continue

            # Try each other position as center of symmetry
            for j, from_pos_ in enumerate(state):
                if i == j:
                    continue

                to_pos = 2 * from_pos_ - from_pos

                # Check bounds: must be <= 10^18 in absolute value
                if abs(to_pos) > 10**18:
                    continue

                # New state: one less at from_pos, one more at to_pos
                new_state_list = list(state)
                new_state_list[i] += to_pos
                new_state_list[i] -= from_pos
                new_state_list[j] = from_pos  # stone j stays at from_pos as center

                new_state_tuple = tuple(sorted(new_state_list))

                if new_state_tuple not in visited:
                    visited.add(new_state_tuple)
                    queue.append((new_state_tuple, ops + [(from_pos, from_pos_)]))

    # No solution found
    return "-1\n"

