def get_prime_factors(num):
    """Get prime factorization with exponents."""
    factors = {}
    d = 2
    while d * d <= num and num > 1:
        while num % d == 0:
            factors[d] = factors.get(d, 0) + 1
            num //= d
        d += 1 if d == 2 else 2  # Skip even numbers after 2
    if num > 1:
        factors[num] = factors.get(num, 0) + 1
    return factors


