            if fall_times[i] < prefix_earliest[pos]:
                prefix_earliest[pos] = fall_times[i]
            if pos > 1:
                prefix_earliest[pos] = min(prefix_earliest[pos], prefix_earliest[pos - 1])

        # suffix_earliest[p] = earliest time among icicles at positions p to n
        suffix_earliest = [float('inf')] * (n + 2)
        for i in range(n - 1, -1, -1):
            pos = i + 1
            if fall_times[i] < suffix_earliest[pos]:
                suffix_earliest[pos] = fall_times[i]
