def solution(input_str):
    import sys
    from functools import lru_cache

    n, k, m = map(int, input_str.strip().split())
    MOD = 10**9 + 7

    if k == 1:
        return str(n % MOD)

    # The key insight: with small k and m, we can think about the problem
    # differently. Let's compute the number of valid sequences directly.
    # 
    # For a sequence of k planets ending at position p, the second-to-last
    # position must be in some valid range. We use DP with memoization.
    #
    # dp[i][relative_positions] = count where relative_positions tracks
    # which positions relative to the ending are visited

    # Let's use a different approach: count sequences by their "shape"
    # Since k <= 12 and m <= 4, the "interesting" range is small

    # Simpler approach: iterate over all possible sequences with pruning
    def count_sequences():
        @lru_cache(maxsize=100000)
        def dfs(last_pos, step, visited_tuple):
            if step == k:
                return 1

            count = 0
            # We can go to any unvisited position in [1, last_pos + m]
            for next_pos in range(1, min(last_pos + m + 1, n + 1)):
                if next_pos not in visited_tuple:
                    new_visited = visited_tuple + (next_pos,)
                    count += dfs(next_pos, step + 1, new_visited)
            return count % MOD

        total = 0
        for start in range(1, n + 1):
            total = (total + dfs(start, 1, (start,))) % MOD
        return total

    result = count_sequences()
    return str(result)

from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, h, m = map(int, lines[0].split())
    restrictions = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        l, r, x, c = map(int, parts)
        restrictions.append((l - 1, r - 1, x, c))  # Convert to 0-indexed

    @lru_cache(maxsize=None)
    def dp(pos, max_vals):
        # pos: current position we're about to decide height for (0 to n)
        # max_vals: tuple of maximum heights encountered so far for each restriction
        if pos == n:
            return 0

        ans = float('-inf')

        for height in range(h + 1):
            # Create new max values by updating for this position
            new_max_vals = list(max_vals)
            for k in range(m):
                if restrictions[k][0] <= pos:
                    new_max_vals[k] = max(new_max_vals[k], height)

            # Calculate fines for restrictions that end at this position
            fines = 0
            for k in range(m):
                l, r, x, c = restrictions[k]
                if r == pos:  # restriction range ends at this position
                    if new_max_vals[k] > x:
                        fines += c

            # Calculate current position gain and recursively solve
            current_gain = height * height
            future = dp(pos + 1, tuple(new_max_vals))

            if future != float('-inf'):
                ans = max(ans, current_gain - fines + future)

        return ans

    return str(dp(0, tuple([0] * m)))
